        new_rows = transpose(new_rows)
    return new_rows, gained, new_rows != grid


def spawn(grid):
    """Place a new tile (90% chance 2, 10% chance 4) in a random empty cell."""
    empties = [(r, c) for r in range(SIZE) for c in range(SIZE) if grid[r][c] == 0]
    if empties:
        r, c = random.choice(empties)
        grid[r][c] = 2 if random.random() < 0.9 else 4


def can_move(grid):
    """True if any empty cell or any adjacent equal pair exists."""
    for r in range(SIZE):
        for c in range(SIZE):
            if grid[r][c] == 0:
                return True
            if c + 1 < SIZE and grid[r][c] == grid[r][c + 1]:
                return True
            if r + 1 < SIZE and grid[r][c] == grid[r + 1][c]:
                return True
    return False


def display(grid, score):
    os.system('cls' if os.name == 'nt' else 'clear')
    highest = max(max(r) for r in grid)
    print(f"Score: {score}    Highest tile: {highest}\n")
    border = "+" + "------+" * SIZE
    print(border)
    for row in grid:
        print("|" + "|".join(f"{v:^6}" if v else "      " for v in row) + "|")
        print(border)
    print("\nArrow keys: move | q: quit")


def main():
    grid = [[0] * SIZE for _ in range(SIZE)]
    score = 0
    spawn(grid)
    spawn(grid)
    while True:
        display(grid, score)
        if not can_move(grid):
            highest = max(max(r) for r in grid)
            print(f"Game over! Final score: {score} | Highest tile: {highest}")
            break
        key = read_key()
        if key in ('q', '\x03'):
            print(f"Quit. Score: {score} | Highest tile: {max(max(r) for r in grid)}")
            break
        if key not in ('up', 'down', 'left', 'right'):
            continue
        new_grid, gained, moved = move(grid, key)
        if moved:
            grid, score = new_grid, score + gained
            spawn(grid)


if __name__ == '__main__':
    try:
        main()
    except KeyboardInterrupt:
        print("\nQuit.")
